import './styles.css'
import './register-service-worker'
import { defaultData } from './data'
import { categories, type AppData, type Category, type Currency, type DayPlace, type DayPlan, type Expense, type PackingCategory, type Status, type TripEssential } from './types'
import { icon } from './icons'
import { calculator, registerCalculatorEvents } from './calculator'
import { normalizeAppData } from './app-data'
import { selectExpenses, type ExpenseSort } from './expense-list'
import { vietnamesePhraseCategories, vietnamesePhrases, type VietnamesePhrase, type VietnamesePhraseCategory } from './phrases'
import { bindTripDocuments, renderTripDocuments, resetTripDocumentViewer } from './trip-documents'

type View = 'overview'|'expenses'|'daily'|'guide'|'calculator'|'documents'|'phrasebook'
const STORAGE_KEY='da-nang-trip-2026-v2'
const PENDING_SAVE_KEY='da-nang-trip-2026-pending-save'
const TRAVELER_KEY='da-nang-trip-2026-traveler'
const PHRASE_CATEGORY_KEY='da-nang-trip-2026-phrase-category'
const views: {id:View; label:string; icon:string}[]=[
  {id:'overview',label:'ภาพรวม',icon:'overview'},{id:'expenses',label:'ค่าใช้จ่าย',icon:'receipt'},{id:'daily',label:'แผนรายวัน',icon:'calendar'},
  {id:'guide',label:'คู่มือทริป',icon:'plane'},{id:'calculator',label:'เครื่องคิดเลข',icon:'calculator'}
]
const mobileViews=views.filter(view=>view.id!=='guide')
const colors=['#087c78','#ef8d3b','#5f8fc9','#d6ad42','#8a77b5','#df6f78','#7d918b']
const categoryLabels:Record<Category,string>={Flights:'เที่ยวบิน',Accommodation:'ที่พัก',Transportation:'การเดินทาง',Food:'อาหาร',Activities:'กิจกรรม',Shopping:'ช้อปปิ้ง',Other:'อื่น ๆ'}
const guideSlides=['หน้าปกและภาพรวมทริป','แผนการเดินทาง 5 วัน','ที่พักและคำแนะนำการเดินทาง','ไฮไลต์วันที่ 1–2','แผนเที่ยววันที่ 3–5','ภาพรวมงบประมาณ']
const clone=<T,>(v:T):T=>JSON.parse(JSON.stringify(v)) as T
type SyncState='loading'|'saving'|'synced'|'offline'
let data:AppData=normalizeAppData(loadData()), view:View='overview', editingId:string|null=null, pendingDelete:string|null=null, editingDayId:string|null=null, editingEssentialId:string|null=null, editingPackingId:string|null=null, query='', categoryFilter='all', statusFilter:Status|'all'='all', payerFilter='all', expenseSort:ExpenseSort='date-desc'
let syncState:SyncState='loading', syncTimer:number|undefined, hasPendingSave=loadPendingSave(), localChangeVersion=0
let guideTimer:number|undefined
let guidePreviewIndex:number|null=null, guidePreviewRotation:0|90=0
let cloudPromise:Promise<typeof import('./cloud')>|undefined
let selectedTravelerId=loadSelectedTraveler(), choosingTraveler=false
let selectedDayId:string|null=null
let phraseCategory=loadPhraseCategory(), phraseQuery=''

function getCloud(){return cloudPromise??=import('./cloud')}
function loadPendingSave(){try{return localStorage.getItem(PENDING_SAVE_KEY)==='true'}catch{return false}}
function loadSelectedTraveler(){try{return localStorage.getItem(TRAVELER_KEY)}catch{return null}}
function loadPhraseCategory():VietnamesePhraseCategory{try{const saved=localStorage.getItem(PHRASE_CATEGORY_KEY);if(vietnamesePhraseCategories.some(category=>category.id===saved))return saved as VietnamesePhraseCategory}catch{/* Use the default category when storage is unavailable. */}return'common'}
function currentTraveler(){return data.settings.travelers.find(person=>person.id===selectedTravelerId)||null}

function loadData():AppData{
  try{const saved=localStorage.getItem(STORAGE_KEY);if(saved)return JSON.parse(saved) as AppData
    const old=localStorage.getItem('trip-budget-v1');if(old){const legacy=JSON.parse(old) as {five?:{items?:{name:string,value:number,note?:string}[]}};const next=clone(defaultData);if(legacy.five?.items){next.expenses=legacy.five.items.map((x,i)=>({id:`legacy-${i}`,date:next.settings.startDate,item:x.name,category:guessCategory(x.name),amount:x.value,currency:'THB',payerId:next.settings.travelers[0].id,status:i<2?'paid':'planned',note:x.note||'นำเข้าจากแผนเดิม'}));return next}}
  }catch{showToast('ไม่สามารถอ่านข้อมูลเดิมได้ จึงใช้ค่าเริ่มต้น','error')}
  return clone(defaultData)
}
function guessCategory(name:string):Category{if(name.includes('เครื่องบิน'))return'Flights';if(name.includes('พัก')||name.includes('Hotel'))return'Accommodation';if(name.includes('รถ')||name.includes('น้ำมัน')||name.includes('สะพาน'))return'Transportation';if(name.includes('กิน')||name.includes('อาหาร'))return'Food';if(name.includes('เที่ยว'))return'Activities';return'Other'}
function saveLocal(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(data))}catch{showToast('บันทึกข้อมูลสำรองในเครื่องไม่สำเร็จ','error')}}
function setPendingSave(pending:boolean){hasPendingSave=pending;try{if(pending)localStorage.setItem(PENDING_SAVE_KEY,'true');else localStorage.removeItem(PENDING_SAVE_KEY)}catch{/* Data remains in the main local backup even if this marker cannot be stored. */}}
function setSyncState(next:SyncState){syncState=next;document.querySelectorAll<HTMLElement>('[data-sync-status]').forEach(el=>{el.className=`sync-status ${next}`;el.textContent=syncText()})}
function syncText(){return syncState==='loading'?'กำลังเชื่อมต่อ':syncState==='saving'?'กำลังบันทึก':syncState==='synced'?'ซิงก์แล้ว':'ออฟไลน์ · เก็บในเครื่อง'}
async function flushSave(){const versionToSave=localChangeVersion;try{const {saveTrip}=await getCloud();await saveTrip(clone(data));if(versionToSave===localChangeVersion){setPendingSave(false);setSyncState('synced')}else{setSyncState('saving');window.clearTimeout(syncTimer);syncTimer=window.setTimeout(()=>void flushSave(),350)}}catch{const wasOffline=syncState==='offline';setSyncState('offline');window.clearTimeout(syncTimer);syncTimer=window.setTimeout(()=>void flushSave(),5000);if(!wasOffline)showToast('ยังส่งข้อมูลขึ้นฐานข้อมูลไม่ได้ เก็บสำรองในเครื่องแล้ว','error')}}
function save(){saveLocal();localChangeVersion+=1;setPendingSave(true);setSyncState('saving');window.clearTimeout(syncTimer);syncTimer=window.setTimeout(()=>void flushSave(),350)}
function toTHB(exp:Expense){return exp.currency==='THB'?exp.amount:exp.amount/data.settings.exchangeRate}
function fmt(value:number,currency:Currency='THB',digits=0){return new Intl.NumberFormat('th-TH',{style:'currency',currency,maximumFractionDigits:digits}).format(value||0)}
function fmtDate(date:string){return new Intl.DateTimeFormat('th-TH',{day:'numeric',month:'short',year:'numeric'}).format(new Date(`${date}T00:00:00`))}
function totals(){const all=data.expenses.reduce((s,e)=>s+toTHB(e),0),paid=data.expenses.filter(e=>e.status==='paid').reduce((s,e)=>s+toTHB(e),0);return{all,paid,planned:all-paid,remaining:data.settings.budgetTHB-all,perPerson:all/data.settings.travelers.length}}
function esc(value:string){return value.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c] as string))}
function mapUrl(name:string,address:string,customUrl:string){const custom=customUrl.trim();if(/^https?:\/\//i.test(custom))return custom;const query=custom||[name,address].filter(Boolean).join(' ');return query?`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`:''}
function telUrl(phone:string){const normalized=phone.replace(/[^\d+]/g,'');return normalized?`tel:${normalized}`:''}
function showToast(message:string,type:'ok'|'error'='ok'){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className=`toast ${type==='error'?'error':''}`;el.setAttribute('role','status');el.textContent=message;document.body.append(el);setTimeout(()=>el.remove(),2600)}
function navHtml(items=views){return items.map(v=>`<button data-view="${v.id}" class="${view===v.id?'active':''}" aria-current="${view===v.id?'page':'false'}">${icon(v.icon)}<span>${v.label}</span></button>`).join('')}
function shell(content:string){return `<div class="app"><header class="mobile-head"><div class="brand"><span class="brand-mark">${icon('plane')}</span><span><strong>ดานัง</strong><small>ทริป 2026</small></span></div><span class="sync-status ${syncState}" data-sync-status>${syncText()}</span><button class="menu-btn" id="openMenu" aria-label="เปิดเมนู">${icon('menu')}</button></header><div class="side-overlay"></div><aside class="sidebar"><div class="side-brand"><span class="brand-mark">${icon('plane')}</span><div><strong>ทริปดานัง</strong><small>26–30 ก.ย. · ${data.settings.travelers.length} คน</small></div></div><nav class="nav" aria-label="เมนูหลัก">${navHtml()}</nav><div class="side-foot"><button class="traveler-switch" type="button" data-change-traveler><span>${icon('users')}</span><span><small>กำลังใช้งานเป็น</small><strong>${esc(currentTraveler()?.name||'เลือกผู้ใช้')}</strong></span></button><div class="side-status"><p class="sync-status ${syncState}" data-sync-status>${syncText()}</p><p>ข้อมูลสำรองอยู่ในอุปกรณ์นี้</p></div><p class="credit">ภาพสะพานมังกรโดย Supanut Arunoprayote · CC BY 4.0</p></div></aside><main class="content">${content}</main>${view==='expenses'?`<button class="mobile-fab" type="button" data-add aria-label="เพิ่มค่าใช้จ่าย">${icon('plus')}<span>เพิ่มค่าใช้จ่าย</span></button>`:''}<nav class="mobile-nav" aria-label="เมนูมือถือ">${navHtml(mobileViews)}</nav></div>`}
function pageHead(title:string,desc:string,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`}
function travelerPicker(){const selected=currentTraveler();return `<div class="modal-backdrop traveler-picker-backdrop"><section class="modal small-modal traveler-picker" role="dialog" aria-modal="true" aria-labelledby="travelerPickerTitle"><div class="traveler-picker-handle" aria-hidden="true"></div><div class="modal-head"><div><h2 id="travelerPickerTitle">คุณคือใคร?</h2><p>เลือกชื่อเพื่อแสดงเช็กลิสต์สัมภาระของคุณ</p></div>${selected?`<button class="icon-btn" type="button" data-close-traveler aria-label="ปิด">${icon('close')}</button>`:''}</div><div class="traveler-options">${data.settings.travelers.map(person=>`<button class="traveler-option ${person.id===selectedTravelerId?'active':''}" type="button" data-select-traveler="${person.id}"><span>${esc(person.name.slice(0,1))}</span><strong>${esc(person.name)}</strong>${person.id===selectedTravelerId?icon('check'):''}</button>`).join('')}</div><p class="hint">ชื่อนี้เก็บไว้เฉพาะในอุปกรณ์นี้ และเปลี่ยนภายหลังได้</p></section></div>`}
function renderGuide(){return `${pageHead('คู่มือทริป','ปัดซ้าย–ขวา หรือปล่อยให้ภาพเลื่อนอัตโนมัติ','<button class="btn" data-view="overview">กลับภาพรวม</button>')}<section class="card guide-card" aria-labelledby="guideTitle"><div class="section-head"><div><h2 id="guideTitle">ภาพรวมทริป</h2></div><span class="guide-counter" id="guideCounter">1 / ${guideSlides.length}</span></div><div class="guide-frame"><button class="guide-arrow guide-prev" type="button" aria-label="ภาพก่อนหน้า">‹</button><div class="guide-track" id="tripGuideTrack">${guideSlides.map((label,index)=>`<figure class="guide-slide"><img src="/trip-guide-${index+1}.jpg" alt="${label}" ${index?'loading="lazy"':''}><figcaption><span>${label}</span><button type="button" data-open-guide-image="${index}">เปิดภาพเต็ม</button></figcaption></figure>`).join('')}</div><button class="guide-arrow guide-next" type="button" aria-label="ภาพถัดไป">›</button></div><div class="guide-dots" role="group" aria-label="เลือกหน้าคู่มือ">${guideSlides.map((label,index)=>`<button type="button" data-guide-index="${index}" class="${index===0?'active':''}" aria-label="${label}" aria-current="${index===0?'true':'false'}"></button>`).join('')}</div></section>`}
function guidePreviewModal(){if(guidePreviewIndex===null)return'';const label=guideSlides[guidePreviewIndex],rotated=guidePreviewRotation===90;return `<div class="modal-backdrop guide-lightbox-backdrop" data-guide-preview-backdrop><section class="guide-lightbox" role="dialog" aria-modal="true" aria-labelledby="guidePreviewTitle"><header class="guide-lightbox-head"><div><h2 id="guidePreviewTitle">${esc(label)}</h2><span>หน้า ${guidePreviewIndex+1} จาก ${guideSlides.length}</span></div><div class="guide-lightbox-actions"><button class="btn compact" type="button" data-rotate-guide aria-pressed="${rotated}">${icon('rotate')} ${rotated?'กลับเป็นแนวนอน':'หมุนเป็นแนวตั้ง'}</button><button class="icon-btn" type="button" data-close-guide-preview aria-label="ปิดภาพเต็ม" autofocus>${icon('close')}</button></div></header><div class="guide-lightbox-stage ${rotated?'rotated':''}" data-guide-preview-stage><img src="/trip-guide-${guidePreviewIndex+1}.jpg" alt="${esc(label)}"></div><nav class="guide-lightbox-nav" aria-label="เปลี่ยนหน้าคู่มือ"><button type="button" data-guide-preview-prev aria-label="หน้าก่อนหน้า">‹ <span>ก่อนหน้า</span></button><strong>${guidePreviewIndex+1} / ${guideSlides.length}</strong><button type="button" data-guide-preview-next aria-label="หน้าถัดไป"><span>ถัดไป</span> ›</button></nav><button class="guide-lightbox-exit" type="button" data-close-guide-preview aria-label="ปิดภาพเต็ม">${icon('close')}<span>ปิด</span></button></section></div>`}
function bindTripGuide(){window.clearInterval(guideTimer);const track=document.querySelector<HTMLElement>('#tripGuideTrack'),slides=[...document.querySelectorAll<HTMLElement>('.guide-slide')],dots=[...document.querySelectorAll<HTMLButtonElement>('[data-guide-index]')],counter=document.querySelector('#guideCounter');if(!track||!slides.length)return;let active=0;const update=(index:number)=>{active=(index+slides.length)%slides.length;dots.forEach((dot,i)=>{dot.classList.toggle('active',i===active);dot.setAttribute('aria-current',String(i===active))});if(counter)counter.textContent=`${active+1} / ${slides.length}`},go=(index:number)=>{update(index);track.scrollTo({left:slides[active].offsetLeft,behavior:'smooth'})},start=()=>{window.clearInterval(guideTimer);if(view==='guide'&&guidePreviewIndex===null&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches)guideTimer=window.setInterval(()=>go(active+1),6500)},stop=()=>window.clearInterval(guideTimer),closePreview=()=>{guidePreviewIndex=null;guidePreviewRotation=0;render()},changePreview=(step:number)=>{if(guidePreviewIndex===null)return;guidePreviewIndex=(guidePreviewIndex+step+guideSlides.length)%guideSlides.length;render()};document.querySelector('.guide-prev')?.addEventListener('click',()=>{go(active-1);start()});document.querySelector('.guide-next')?.addEventListener('click',()=>{go(active+1);start()});dots.forEach((dot,index)=>dot.addEventListener('click',()=>{go(index);start()}));document.querySelectorAll<HTMLElement>('[data-open-guide-image]').forEach(button=>button.addEventListener('click',()=>{guidePreviewIndex=Number(button.dataset.openGuideImage);guidePreviewRotation=0;stop();render()}));document.querySelectorAll('[data-close-guide-preview]').forEach(button=>button.addEventListener('click',closePreview));document.querySelector<HTMLElement>('[data-guide-preview-backdrop]')?.addEventListener('click',event=>{if(event.target===event.currentTarget)closePreview()});document.querySelector<HTMLElement>('[data-guide-preview-stage]')?.addEventListener('click',event=>{if(event.target===event.currentTarget)closePreview()});document.querySelector('[data-rotate-guide]')?.addEventListener('click',()=>{guidePreviewRotation=guidePreviewRotation===0?90:0;render()});document.querySelector('[data-guide-preview-prev]')?.addEventListener('click',()=>changePreview(-1));document.querySelector('[data-guide-preview-next]')?.addEventListener('click',()=>changePreview(1));track.addEventListener('scroll',()=>{const width=track.clientWidth;if(width)update(Math.round(track.scrollLeft/width))},{passive:true});track.addEventListener('pointerdown',stop);track.addEventListener('pointerup',start);track.addEventListener('mouseenter',stop);track.addEventListener('mouseleave',start);track.addEventListener('focusin',stop);track.addEventListener('focusout',start);start()}
function bindGuideShortcut(){document.querySelector('[data-open-guide]')?.addEventListener('click',()=>{view='guide';render();window.scrollTo(0,0)})}

const packingCategories: {id:PackingCategory; label:string}[]=[
  {id:'documents',label:'เอกสาร'},{id:'clothes',label:'เสื้อผ้า'},{id:'medicine',label:'ยา'},{id:'equipment',label:'อุปกรณ์'},{id:'personal',label:'ของใช้ส่วนตัว'}
]
const essentialLabels={flight:'เที่ยวบิน',stay:'ที่พัก',emergency:'ฉุกเฉิน'} as const

function essentialCard(item:TripEssential){const destination=mapUrl(item.title,item.address,item.mapUrl),phone=telUrl(item.phone);return `<article class="essential-item"><div class="essential-top"><span class="category">${essentialLabels[item.kind]}</span><button class="icon-btn" type="button" data-edit-essential="${item.id}" aria-label="แก้ไข ${esc(item.title)}">${icon('edit')}</button></div><h3>${esc(item.title)}</h3>${item.details?`<p>${esc(item.details)}</p>`:'<p class="hint">ยังไม่ได้เพิ่มรายละเอียด</p>'}${item.bookingRef?`<div class="essential-line"><span>เลขการจอง</span><strong>${esc(item.bookingRef)}</strong></div>`:''}${item.address?`<div class="essential-line"><span>ที่อยู่</span><strong>${esc(item.address)}</strong></div>`:''}<div class="utility-actions">${item.bookingRef?`<button class="btn compact" type="button" data-copy="${esc(item.bookingRef)}">${icon('copy')} คัดลอกเลขจอง</button>`:''}${phone?`<a class="btn compact" href="${esc(phone)}">${icon('phone')} โทร</a>`:''}${destination?`<a class="btn compact" href="${esc(destination)}" target="_blank" rel="noopener">${icon('map')} เปิดแผนที่</a>`:''}</div></article>`}

function packingSection(){const traveler=currentTraveler(),items=data.packingItems.filter(item=>item.ownerId===traveler?.id),packed=items.filter(item=>item.packed).length;return `<section class="card utility-section" id="packingChecklist"><div class="section-head"><div><h2>เช็กลิสต์สัมภาระของ${esc(traveler?.name||'คุณ')}</h2><small>${packed} / ${items.length} รายการพร้อมแล้ว · เห็นเฉพาะรายการของคุณ</small></div><button class="btn compact" type="button" data-add-packing>${icon('plus')} เพิ่มรายการ</button></div><div class="packing-groups">${packingCategories.map(category=>{const categoryItems=items.filter(item=>item.category===category.id);return `<section class="packing-group"><h3>${category.label}</h3>${categoryItems.length?categoryItems.map(item=>`<div class="packing-row ${item.packed?'packed':''}"><label><input type="checkbox" data-toggle-packing="${item.id}" ${item.packed?'checked':''}><span>${esc(item.name)}</span></label><div class="row-actions"><button class="icon-btn" type="button" data-edit-packing="${item.id}" aria-label="แก้ไข ${esc(item.name)}">${icon('edit')}</button><button class="icon-btn" type="button" data-delete-packing="${item.id}" aria-label="ลบ ${esc(item.name)}">${icon('trash')}</button></div></div>`).join(''):'<p class="hint">ยังไม่มีรายการ</p>'}</section>`}).join('')}</div></section>`}

function phraseRow(phrase:VietnamesePhrase){return `<article class="phrase-row phrasebook-row"><div><span>${esc(phrase.thai)}</span><strong lang="vi">${esc(phrase.vietnamese)}</strong><small>อ่านว่า · ${esc(phrase.pronunciation)}</small></div><button class="icon-btn phrase-speak" type="button" data-speak-vietnamese="${esc(phrase.vietnamese)}" aria-label="ฟังเสียง ${esc(phrase.thai)}" aria-pressed="false">${icon('speaker')}</button></article>`}

function phraseSection(){const featured=vietnamesePhrases.filter(phrase=>phrase.featured).slice(0,6);return `<section class="card utility-section phrase-preview" id="vietnamesePhrases"><div class="section-head"><div><h2>ภาษาเวียดนามใช้บ่อย</h2><small>แตะปุ่มลำโพงเพื่อฟังเสียงภาษาเวียดนาม</small></div><button class="btn compact" type="button" data-view="phrasebook">เปิดสมุดภาษา</button></div><div class="phrase-preview-grid">${featured.map(phrase=>phraseRow(phrase)).join('')}</div></section>`}

function visiblePhrases(){const queryText=phraseQuery.trim().toLocaleLowerCase();return vietnamesePhrases.filter(phrase=>{if(!queryText)return phrase.category===phraseCategory;return `${phrase.thai} ${phrase.vietnamese} ${phrase.pronunciation} ${phrase.keywords||''}`.toLocaleLowerCase().includes(queryText)})}

function phrasebookResults(){const phrases=visiblePhrases(),category=vietnamesePhraseCategories.find(item=>item.id===phraseCategory),isNumberGrid=!phraseQuery.trim()&&phraseCategory==='numbers';return `<div class="phrasebook-result-head"><strong>${phraseQuery.trim()?`ผลการค้นหา ${phrases.length} รายการ`:`${category?.label||''} · ${phrases.length} รายการ`}</strong><small>แตะปุ่มลำโพงเพื่อฟังเสียง</small></div>${phrases.length?`<div class="phrasebook-list ${isNumberGrid?'number-grid':''}">${phrases.map(phrase=>phraseRow(phrase)).join('')}</div>`:`<div class="empty phrasebook-empty">${icon('search',32)}<strong>ไม่พบคำที่ค้นหา</strong><span>ลองใช้คำสั้น ๆ เช่น ข้าว, สอง, สวย หรือ ห้องน้ำ</span></div>`}`}

function phrasebook(){return `${pageHead('สมุดภาษาเวียดนาม','ค้นหาคำที่ต้องใช้ แล้วแตะลำโพงให้โทรศัพท์พูดภาษาเวียดนาม','<button class="btn" type="button" data-view="guide">กลับคู่มือทริป</button>')}<section class="card phrasebook-card"><label class="search phrasebook-search">${icon('search')}<input class="input" id="phraseSearch" value="${esc(phraseQuery)}" placeholder="ค้นหา เช่น ข้าว, สอง, สวย, ห้องน้ำ" aria-label="ค้นหาคำหรือประโยคภาษาเวียดนาม"></label><nav class="phrasebook-categories" aria-label="หมวดคำภาษาเวียดนาม">${vietnamesePhraseCategories.map(category=>`<button type="button" data-phrase-category="${category.id}" class="${!phraseQuery.trim()&&phraseCategory===category.id?'active':''}" aria-pressed="${!phraseQuery.trim()&&phraseCategory===category.id}">${category.label}</button>`).join('')}</nav><div id="phrasebookResults" aria-live="polite">${phrasebookResults()}</div></section>`}

function tripGuideUtilities(){return `<section class="card utility-section" id="tripEssentials"><div class="section-head"><div><h2>ข้อมูลสำคัญของทริป</h2><small>เที่ยวบิน ที่พัก เลขการจอง และเบอร์ติดต่อที่ต้องใช้</small></div></div><div class="essential-grid">${data.tripEssentials.map(essentialCard).join('')}</div><p class="hint privacy-note">เก็บเฉพาะข้อมูลการเดินทางที่จำเป็น ไม่ควรใส่เลขพาสปอร์ตหรือข้อมูลส่วนตัวสำคัญ</p></section>${packingSection()}${phraseSection()}`}

function dailyPlacesHtml(day:DayPlan){if(!day.places.length)return'';return `<div class="day-places"><span class="metric-label">สถานที่</span>${day.places.map(place=>{const destination=mapUrl(place.name,place.address,place.mapUrl);return `<div class="day-place"><div><strong>${esc(place.name||'สถานที่')}</strong>${place.address?`<span>${esc(place.address)}</span>`:''}</div>${destination?`<a class="btn compact" href="${esc(destination)}" target="_blank" rel="noopener">${icon('map')} เปิดแผนที่</a>`:''}</div>`}).join('')}</div>`}

function documentShortcut(){return `<section class="card document-shortcut"><span>${icon('file')}</span><div><strong>เอกสารทริป</strong><small>ตั๋ว การจอง และประกัน · ดาวน์โหลดไว้เปิดดูแบบออฟไลน์ได้</small></div><button class="btn compact" type="button" data-view="documents">เปิดเอกสาร</button></section>`}
function injectViewUtilities(){if(view==='overview')document.querySelector('.hero')?.insertAdjacentHTML('afterend',documentShortcut());if(view==='guide')document.querySelector('.guide-card')?.insertAdjacentHTML('afterend',`${documentShortcut()}${tripGuideUtilities()}`)}

function placeFields(place?:DayPlace){const id=place?.id||crypto.randomUUID();return `<div class="place-editor-row" data-place-id="${id}"><div class="field"><label>ชื่อสถานที่</label><input class="input place-name" value="${esc(place?.name||'')}" placeholder="เช่น Golden Bridge"></div><div class="field"><label>ที่อยู่</label><input class="input place-address" value="${esc(place?.address||'')}" placeholder="เว้นว่างได้"></div><div class="field place-link"><label>ลิงก์แผนที่หรือพิกัด</label><input class="input place-map" value="${esc(place?.mapUrl||'')}" placeholder="เว้นว่างเพื่อค้นจากชื่อและที่อยู่"></div><button class="icon-btn" type="button" data-remove-place aria-label="นำสถานที่นี้ออก">${icon('trash')}</button></div>`}

function injectDayPlacesEditor(){const form=document.querySelector('#dayForm'),actions=form?.querySelector('.modal-actions');if(!form||!actions||form.querySelector('#dayPlaceRows'))return;const day=editingDayId?data.days.find(item=>item.id===editingDayId):null,places=day?.places.length?day.places:[{id:crypto.randomUUID(),name:'',address:'',mapUrl:''}];actions.insertAdjacentHTML('beforebegin',`<fieldset class="place-editor"><legend>สถานที่และแผนที่</legend><p class="hint">ถ้าไม่ใส่ลิงก์ แอปจะค้นหา Google Maps จากชื่อและที่อยู่ให้</p><div id="dayPlaceRows">${places.map(placeFields).join('')}</div><button class="btn compact" type="button" data-add-place>${icon('plus')} เพิ่มสถานที่</button></fieldset>`);form.querySelector('[data-add-place]')?.addEventListener('click',()=>document.querySelector('#dayPlaceRows')?.insertAdjacentHTML('beforeend',placeFields()));form.querySelector('#dayPlaceRows')?.addEventListener('click',event=>{const button=(event.target as HTMLElement).closest('[data-remove-place]');button?.closest('.place-editor-row')?.remove()})}

function essentialModal(){const item=data.tripEssentials.find(essential=>essential.id===editingEssentialId);if(!item)return'';return `<div class="modal-backdrop"><form class="modal" id="essentialForm" role="dialog" aria-modal="true" aria-labelledby="essentialTitle"><div class="modal-head"><h2 id="essentialTitle">แก้ไขข้อมูล${essentialLabels[item.kind]}</h2><button class="icon-btn" type="button" data-close-utility aria-label="ปิด">${icon('close')}</button></div><div class="form-grid"><div class="field"><label for="essentialName">ชื่อรายการ</label><input class="input" id="essentialName" value="${esc(item.title)}" required autofocus></div><div class="field"><label for="essentialDetails">เที่ยวบิน / เวลาเช็กอิน–เช็กเอาต์ / หมายเหตุ</label><input class="input" id="essentialDetails" value="${esc(item.details)}"></div><div class="field"><label for="essentialBooking">เลขการจอง</label><input class="input" id="essentialBooking" value="${esc(item.bookingRef)}"></div><div class="field"><label for="essentialPhone">เบอร์ติดต่อ</label><input class="input" id="essentialPhone" type="tel" value="${esc(item.phone)}"></div><div class="field"><label for="essentialAddress">ที่อยู่</label><textarea class="textarea" id="essentialAddress" rows="2">${esc(item.address)}</textarea></div><div class="field"><label for="essentialMap">ลิงก์ Google Maps หรือพิกัด</label><input class="input" id="essentialMap" value="${esc(item.mapUrl)}" placeholder="เว้นว่างเพื่อค้นหาจากชื่อและที่อยู่"></div></div><div class="modal-actions"><button class="btn" type="button" data-close-utility>ยกเลิก</button><button class="btn primary" type="submit">บันทึกข้อมูล</button></div></form></div>`}

function packingModal(){const ownerId=currentTraveler()?.id,item=editingPackingId?data.packingItems.find(packing=>packing.id===editingPackingId&&packing.ownerId===ownerId):null;return `<div class="modal-backdrop"><form class="modal small-modal" id="packingForm" role="dialog" aria-modal="true" aria-labelledby="packingTitle"><div class="modal-head"><h2 id="packingTitle">${item?'แก้ไข':'เพิ่ม'}รายการสัมภาระ</h2><button class="icon-btn" type="button" data-close-utility aria-label="ปิด">${icon('close')}</button></div><div class="form-grid"><div class="field"><label for="packingName">รายการ</label><input class="input" id="packingName" value="${esc(item?.name||'')}" required autofocus></div><div class="field"><label for="packingCategory">หมวดหมู่</label><select class="select" id="packingCategory">${packingCategories.map(category=>`<option value="${category.id}" ${item?.category===category.id?'selected':''}>${category.label}</option>`).join('')}</select></div></div><div class="modal-actions"><button class="btn" type="button" data-close-utility>ยกเลิก</button><button class="btn primary" type="submit">บันทึกรายการ</button></div></form></div>`}

function closeUtilityModal(){editingEssentialId=null;editingPackingId=null;document.body.dataset.addingPacking='false';render()}

function bindTripUtilities(){const ownerId=currentTraveler()?.id;document.querySelectorAll<HTMLElement>('[data-open-guide-section]').forEach(button=>button.addEventListener('click',()=>{const section=button.dataset.openGuideSection;view='guide';render();requestAnimationFrame(()=>document.getElementById(section||'')?.scrollIntoView({block:'start'}))}));document.querySelectorAll<HTMLElement>('[data-edit-essential]').forEach(button=>button.addEventListener('click',()=>{editingEssentialId=button.dataset.editEssential||null;render()}));document.querySelectorAll<HTMLInputElement>('[data-toggle-packing]').forEach(input=>input.addEventListener('change',()=>{const item=data.packingItems.find(packing=>packing.id===input.dataset.togglePacking&&packing.ownerId===ownerId);if(item){item.packed=input.checked;save();render()}}));document.querySelector('[data-add-packing]')?.addEventListener('click',()=>{editingPackingId=null;document.body.dataset.addingPacking='true';render()});document.querySelectorAll<HTMLElement>('[data-edit-packing]').forEach(button=>button.addEventListener('click',()=>{editingPackingId=button.dataset.editPacking||null;document.body.dataset.addingPacking='false';render()}));document.querySelectorAll<HTMLElement>('[data-delete-packing]').forEach(button=>button.addEventListener('click',()=>{const item=data.packingItems.find(packing=>packing.id===button.dataset.deletePacking&&packing.ownerId===ownerId);if(!item||!confirm(`ลบ “${item.name}” ออกจากเช็กลิสต์หรือไม่?`))return;data.packingItems=data.packingItems.filter(packing=>packing.id!==item.id);save();render();showToast('ลบรายการแล้ว')}));document.querySelectorAll<HTMLElement>('[data-copy]').forEach(button=>button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(button.dataset.copy||'');showToast('คัดลอกแล้ว')}catch{showToast('คัดลอกไม่สำเร็จ','error')}}));document.querySelectorAll('[data-close-utility]').forEach(button=>button.addEventListener('click',closeUtilityModal));document.querySelector<HTMLFormElement>('#essentialForm')?.addEventListener('submit',event=>{event.preventDefault();const item=data.tripEssentials.find(essential=>essential.id===editingEssentialId);if(!item)return;const value=(id:string)=>document.querySelector<HTMLInputElement|HTMLTextAreaElement>(`#${id}`)?.value.trim()||'';item.title=value('essentialName');item.details=value('essentialDetails');item.bookingRef=value('essentialBooking');item.phone=value('essentialPhone');item.address=value('essentialAddress');item.mapUrl=value('essentialMap');editingEssentialId=null;save();render();showToast('บันทึกข้อมูลสำคัญแล้ว')});document.querySelector<HTMLFormElement>('#packingForm')?.addEventListener('submit',event=>{event.preventDefault();const name=document.querySelector<HTMLInputElement>('#packingName')?.value.trim()||'',category=document.querySelector<HTMLSelectElement>('#packingCategory')?.value as PackingCategory;if(!name||!ownerId)return;const item=editingPackingId?data.packingItems.find(packing=>packing.id===editingPackingId&&packing.ownerId===ownerId):null;if(item){item.name=name;item.category=category}else data.packingItems.push({id:crypto.randomUUID(),ownerId,name,category,packed:false});editingPackingId=null;document.body.dataset.addingPacking='false';save();render();showToast('บันทึกเช็กลิสต์แล้ว')})}
function overview(){const t=totals(),traveler=currentTraveler(),catTotals=categories.map(c=>({name:categoryLabels[c],value:data.expenses.filter(e=>e.category===c).reduce((s,e)=>s+toTHB(e),0)})).filter(x=>x.value>0);const degs=catTotals.reduce<{name:string,value:number,color:string,start:number,end:number}[]>((a,x,i)=>{const start=a.at(-1)?.end||0;const end=start+(x.value/t.all*360);a.push({...x,color:colors[i],start,end});return a},[]);const gradient=degs.map(x=>`${x.color} ${x.start}deg ${x.end}deg`).join(',');const spentPct=Math.min(100,t.all/data.settings.budgetTHB*100);return `${pageHead(traveler?`สวัสดี ${esc(traveler.name)}`:'ภาพรวมทริป','งบประมาณและค่าใช้จ่ายของผู้เดินทาง 4 คน','<button class="btn" type="button" data-change-traveler>'+icon('users')+' เปลี่ยนผู้ใช้</button><button class="btn" data-open-guide>'+icon('plane')+' คู่มือทริป</button>')}<section class="hero"><img src="/da-nang-dragon-bridge.jpg" alt="สะพานมังกรเหนือแม่น้ำฮันในดานังยามค่ำคืน"><div class="hero-content"><span class="tag">เวียดนาม · 2026</span><h2>${esc(data.settings.tripName)}</h2><p>วางแผนให้ครบ จ่ายอย่างสบายใจ แล้วออกไปสนุกกับดานัง</p><div class="hero-meta"><span>${icon('calendar',18)} ${fmtDate(data.settings.startDate)} — ${fmtDate(data.settings.endDate)}</span><span>${icon('users',18)} ${data.settings.travelers.length} คน</span></div></div></section><section class="grid summary-grid"><div class="card"><div class="metric-label">งบประมาณรวม</div><div class="metric-value">${fmt(data.settings.budgetTHB)}</div><div class="metric-sub">งบรวมของทริป</div></div><div class="card"><div class="metric-label">จ่ายแล้ว</div><div class="metric-value">${fmt(t.paid)}</div><div class="metric-sub">รายการที่จ่ายแล้ว</div></div><div class="card"><div class="metric-label">คาดการณ์</div><div class="metric-value">${fmt(t.planned)}</div><div class="metric-sub">รายการที่วางแผนไว้</div></div><div class="card accent"><div class="metric-label">งบคงเหลือ</div><div class="metric-value">${fmt(t.remaining)}</div><div class="metric-sub">หลังรวมรายการทั้งหมด</div></div><div class="card"><div class="metric-label">เฉลี่ยต่อคน</div><div class="metric-value">${fmt(t.perPerson)}</div><div class="metric-sub">หาร ${data.settings.travelers.length} คน</div></div></section><section class="grid section-grid"><article class="card"><div class="section-head"><div><h2>ค่าใช้จ่ายตามหมวดหมู่</h2><small>รวมเงินบาทและดองเวียดนามหลังแปลงค่า</small></div></div><div class="chart-wrap"><div class="donut" role="img" aria-label="กราฟค่าใช้จ่ายตามหมวดหมู่" style="background:conic-gradient(${gradient})"></div><div class="legend">${degs.map(x=>`<div class="legend-row"><span class="dot" style="background:${x.color}"></span><span>${x.name}</span><strong>${fmt(x.value)}</strong></div>`).join('')}</div></div></article><article class="card"><div class="section-head"><div><h2>งบประมาณเทียบค่าใช้จ่าย</h2><small>รวมรายการจ่ายแล้วและคาดการณ์</small></div></div><div class="budget-bars"><div><div class="bar-label"><span>งบประมาณ</span><strong>${fmt(data.settings.budgetTHB)}</strong></div><div class="bar"><span style="width:100%"></span></div></div><div><div class="bar-label"><span>ค่าใช้จ่ายทั้งหมด</span><strong>${fmt(t.all)}</strong></div><div class="bar orange"><span style="width:${spentPct}%"></span></div></div></div></article></section>`}
function filteredExpenses(){return selectExpenses(data.expenses,{query,category:categoryFilter,status:statusFilter,payerId:payerFilter,sort:expenseSort},toTHB,id=>data.settings.travelers.find(person=>person.id===id)?.name||'')}
function expenseResults(){const rows=filteredExpenses(),total=rows.reduce((sum,expense)=>sum+toTHB(expense),0),actions=(e:Expense)=>`<div class="row-actions"><button class="icon-btn expense-action" data-edit="${e.id}" aria-label="แก้ไข ${esc(e.item)}">${icon('edit')}<span>แก้ไข</span></button><button class="icon-btn expense-action danger-action" data-delete="${e.id}" aria-label="ลบ ${esc(e.item)}">${icon('trash')}<span>ลบ</span></button></div>`;return `<div class="expense-result-meta" aria-live="polite"><strong>${rows.length} รายการ</strong><span>รวม ${fmt(total)}</span></div>${rows.length?`<div class="table-scroll expense-table"><table><thead><tr><th>วันที่</th><th>รายการ</th><th>หมวดหมู่</th><th>จำนวนเงิน</th><th>ผู้จ่าย</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody>${rows.map(e=>`<tr><td>${fmtDate(e.date)}</td><td><strong>${esc(e.item)}</strong><div class="metric-sub">${esc(e.note||'—')}</div></td><td><span class="category">${categoryLabels[e.category]}</span></td><td><strong>${fmt(e.amount,e.currency,e.currency==='VND'?0:2)}</strong>${e.currency==='VND'?`<div class="metric-sub">≈ ${fmt(toTHB(e))}</div>`:''}</td><td>${esc(data.settings.travelers.find(p=>p.id===e.payerId)?.name||'—')}</td><td><span class="status ${e.status}">${e.status==='paid'?'จ่ายแล้ว':'คาดการณ์'}</span></td><td>${actions(e)}</td></tr>`).join('')}</tbody></table></div><div class="expense-mobile-list">${rows.map(e=>`<article class="expense-mobile-card"><div class="expense-mobile-head"><div><strong>${esc(e.item)}</strong><span>${fmtDate(e.date)}</span></div><div class="expense-mobile-amount"><strong>${fmt(e.amount,e.currency,e.currency==='VND'?0:2)}</strong>${e.currency==='VND'?`<span>≈ ${fmt(toTHB(e))}</span>`:''}</div></div><div class="expense-mobile-tags"><span class="category">${categoryLabels[e.category]}</span><span class="status ${e.status}">${e.status==='paid'?'จ่ายแล้ว':'คาดการณ์'}</span></div><details class="expense-mobile-details"><summary>ดูรายละเอียด</summary><div class="expense-mobile-detail-body"><dl><div><dt>ผู้จ่าย</dt><dd>${esc(data.settings.travelers.find(p=>p.id===e.payerId)?.name||'—')}</dd></div><div><dt>หมายเหตุ</dt><dd>${esc(e.note||'ไม่มีหมายเหตุ')}</dd></div></dl>${actions(e)}</div></details></article>`).join('')}</div>`:`<div class="empty">${icon('receipt',34)}<strong>ไม่พบรายการค่าใช้จ่าย</strong><span>ลองเปลี่ยนตัวกรองหรือคำค้นหา</span></div>`}`}
function expenseTable(){return `${pageHead('รายการค่าใช้จ่าย','เพิ่ม แก้ไข ค้นหา และติดตามสถานะการชำระ','<button class="btn primary" data-add>'+icon('plus')+' เพิ่มรายการ</button>')}<section class="card table-card"><div class="toolbar expense-toolbar"><label class="search">${icon('search')}<input class="input" id="expenseSearch" value="${esc(query)}" placeholder="ค้นหารายการ หมายเหตุ หรือผู้จ่าย" aria-label="ค้นหารายการ"></label><details class="expense-filter-details"><summary>ตัวกรองและการเรียง</summary><div class="expense-filter-panel"><select class="select" id="expenseCategory" aria-label="กรองหมวดหมู่"><option value="all">ทุกหมวดหมู่</option>${categories.map(c=>`<option value="${c}" ${categoryFilter===c?'selected':''}>${categoryLabels[c]}</option>`).join('')}</select><select class="select" id="expenseStatus" aria-label="กรองสถานะ"><option value="all">ทุกสถานะ</option><option value="paid" ${statusFilter==='paid'?'selected':''}>จ่ายแล้ว</option><option value="planned" ${statusFilter==='planned'?'selected':''}>คาดการณ์</option></select><select class="select" id="expensePayer" aria-label="กรองผู้จ่าย"><option value="all">ผู้จ่ายทุกคน</option>${data.settings.travelers.map(person=>`<option value="${person.id}" ${payerFilter===person.id?'selected':''}>${esc(person.name)}</option>`).join('')}</select><select class="select" id="expenseSort" aria-label="เรียงรายการ"><option value="date-desc" ${expenseSort==='date-desc'?'selected':''}>วันที่: ใหม่ไปเก่า</option><option value="date-asc" ${expenseSort==='date-asc'?'selected':''}>วันที่: เก่าไปใหม่</option><option value="amount-desc" ${expenseSort==='amount-desc'?'selected':''}>ยอด: มากไปน้อย</option><option value="amount-asc" ${expenseSort==='amount-asc'?'selected':''}>ยอด: น้อยไปมาก</option><option value="category" ${expenseSort==='category'?'selected':''}>หมวดหมู่</option><option value="status" ${expenseSort==='status'?'selected':''}>สถานะ</option></select><button class="btn" id="clearExpenseFilters" type="button">ล้างตัวกรอง</button></div></details></div><div id="expenseResults">${expenseResults()}</div></section>`}
function updateExpenseResults(){const root=document.querySelector('#expenseResults');if(!root)return;root.innerHTML=expenseResults();bindExpenseRows()}
function bindExpenseRows(){document.querySelectorAll<HTMLElement>('[data-edit]').forEach(b=>b.onclick=()=>{editingId=b.dataset.edit||null;document.body.dataset.adding='false';render()});document.querySelectorAll<HTMLElement>('[data-delete]').forEach(b=>b.onclick=()=>{pendingDelete=b.dataset.delete||null;render()})}
function bindExpenseFilters(){const search=document.querySelector<HTMLInputElement>('#expenseSearch');if(search)search.oninput=()=>{query=search.value;updateExpenseResults()};const bindSelect=(id:string,update:(value:string)=>void)=>{const select=document.querySelector<HTMLSelectElement>(`#${id}`);if(select)select.onchange=()=>{update(select.value);updateExpenseResults()}};bindSelect('expenseCategory',value=>categoryFilter=value);bindSelect('expenseStatus',value=>statusFilter=value as Status|'all');bindSelect('expensePayer',value=>payerFilter=value);bindSelect('expenseSort',value=>expenseSort=value as ExpenseSort);document.querySelector('#clearExpenseFilters')?.addEventListener('click',()=>{query='';categoryFilter='all';statusFilter='all';payerFilter='all';expenseSort='date-desc';render()})}
function dailyGuideCarousel(){return `<section class="card daily-overview" aria-labelledby="dailyOverviewTitle"><div class="section-head"><div><h2 id="dailyOverviewTitle">ภาพรวมทริป</h2><small>เลื่อนดูภาพรวม หรือแตะเปิดภาพเต็ม</small></div><span class="guide-counter" id="guideCounter">1 / ${guideSlides.length}</span></div><div class="guide-frame"><button class="guide-arrow guide-prev" type="button" aria-label="ภาพก่อนหน้า">‹</button><div class="guide-track" id="tripGuideTrack">${guideSlides.map((label,index)=>`<figure class="guide-slide"><img src="/trip-guide-${index+1}.jpg" alt="${label}" ${index?'loading="lazy"':''}><figcaption><span>${label}</span><button type="button" data-open-guide-image="${index}">เปิดภาพเต็ม</button></figcaption></figure>`).join('')}</div><button class="guide-arrow guide-next" type="button" aria-label="ภาพถัดไป">›</button></div><div class="guide-dots" role="group" aria-label="เลือกภาพรวมทริป">${guideSlides.map((label,index)=>`<button type="button" data-guide-index="${index}" class="${index===0?'active':''}" aria-label="${label}" aria-current="${index===0?'true':'false'}"></button>`).join('')}</div></section>`}
function dayAgenda(activities:string){const items=activities.split(/\n|·/).map(item=>item.trim()).filter(Boolean);return `<section class="day-agenda"><div class="day-section-title"><span>${icon('checklist')}</span><div><h4>แผนของวันนี้</h4><small>ลำดับกิจกรรมและข้อมูลที่ควรรู้</small></div></div><ol>${(items.length?items:['ยังไม่ได้เพิ่มกำหนดการ']).map((item,index)=>`<li><span>${index+1}</span><strong>${esc(item)}</strong></li>`).join('')}</ol></section>`}
function daily(){const days=[...data.days].sort((a,b)=>a.date.localeCompare(b.date));if(days.length&&!days.some(day=>day.id===selectedDayId))selectedDayId=days[0].id;const selected=days.find(day=>day.id===selectedDayId),selectedIndex=selected?days.indexOf(selected):-1;return `${pageHead('แผนรายวัน','เลือกวันเพื่อดูกำหนดการ สถานที่ และเส้นทาง','<button class="btn primary" data-add-day>'+icon('plus')+' เพิ่มวัน</button>')}${dailyGuideCarousel()}${days.length?`<section class="day-picker" role="tablist" aria-label="เลือกวันเดินทาง">${days.map((day,index)=>`<button type="button" role="tab" data-select-day="${day.id}" class="${day.id===selectedDayId?'active':''}" aria-selected="${day.id===selectedDayId}"><small>วันที่ ${index+1}</small><strong>${new Intl.DateTimeFormat('th-TH',{day:'numeric',month:'short'}).format(new Date(`${day.date}T00:00:00`))}</strong></button>`).join('')}</section>`:''}${selected?`<article class="card day-focus" data-day-id="${selected.id}"><div class="day-main"><div class="datebox"><small>วันที่ ${selectedIndex+1}</small><span>${new Date(`${selected.date}T00:00:00`).getDate()}</span></div><div><h3>${esc(selected.title)}</h3><small>${fmtDate(selected.date)}</small></div><div class="row-actions"><button class="icon-btn" data-edit-day="${selected.id}" aria-label="แก้ไข ${esc(selected.title)}">${icon('edit')}</button><button class="icon-btn" data-delete-day="${selected.id}" aria-label="ลบ ${esc(selected.title)}">${icon('trash')}</button></div></div><div class="day-focus-grid">${dayAgenda(selected.activities)}<section class="day-location-section"><div class="day-section-title"><span>${icon('map')}</span><div><h4>สถานที่และเส้นทาง</h4><small>แตะเปิดแผนที่เมื่อต้องการเดินทาง</small></div></div>${dailyPlacesHtml(selected)||'<p class="hint">ยังไม่ได้เพิ่มสถานที่</p>'}</section></div></article>`:`<div class="card empty">${icon('calendar',34)}<strong>ยังไม่มีแผนรายวัน</strong><span>เพิ่มวันแรกเพื่อเริ่มวางกำหนดการและสถานที่</span></div>`}`}
function dayModal(){const day=editingDayId?data.days.find(item=>item.id===editingDayId):null;return `<div class="modal-backdrop"><form class="modal" id="dayForm" role="dialog" aria-modal="true" aria-labelledby="dayModalTitle"><div class="modal-head"><h2 id="dayModalTitle">${day?'แก้ไข':'เพิ่ม'}แผนรายวัน</h2><button class="icon-btn" type="button" data-close-day aria-label="ปิด">${icon('close')}</button></div><div class="form-grid"><div class="field"><label for="dayDate">วันที่</label><input class="input" id="dayDate" type="date" value="${day?.date||data.settings.startDate}" required></div><div class="field"><label for="dayTitle">ชื่อแผน</label><input class="input" id="dayTitle" value="${esc(day?.title||'')}" required autofocus></div><div class="field wide"><label for="dayActivities">กำหนดการและข้อมูลที่ควรรู้</label><textarea class="textarea" id="dayActivities" rows="4" placeholder="แยกแต่ละกิจกรรมด้วย · หรือขึ้นบรรทัดใหม่">${esc(day?.activities||'')}</textarea></div></div><div class="modal-actions"><button class="btn" type="button" data-close-day>ยกเลิก</button><button class="btn primary" type="submit">บันทึกแผน</button></div></form></div>`}
function injectExpenseDaySelector(){const date=document.querySelector<HTMLInputElement>('#expDate'),form=document.querySelector('#expenseForm');if(!date||!form||form.querySelector('#expDay'))return;const exp=editingId?data.expenses.find(item=>item.id===editingId):null,selected=exp?.dayId||document.body.dataset.expenseDay||'',field=`<div class="field"><label for="expDay">แผนรายวัน</label><select class="select" id="expDay"><option value="">นอกแผนรายวัน</option>${[...data.days].sort((a,b)=>a.date.localeCompare(b.date)).map(day=>`<option value="${day.id}" ${selected===day.id?'selected':''}>${fmtDate(day.date)} · ${esc(day.title)}</option>`).join('')}</select></div>`;date.closest('.field')?.insertAdjacentHTML('afterend',field);document.querySelector<HTMLSelectElement>('#expDay')?.addEventListener('change',event=>{const day=data.days.find(item=>item.id===(event.currentTarget as HTMLSelectElement).value);if(day)date.value=day.date})}
function closeDayModal(){editingDayId=null;document.body.dataset.addingDay='false';render()}
function submitDay(event:Event){event.preventDefault();const date=document.querySelector<HTMLInputElement>('#dayDate')?.value||'',title=document.querySelector<HTMLInputElement>('#dayTitle')?.value.trim()||'',activities=document.querySelector<HTMLTextAreaElement>('#dayActivities')?.value.trim()||'',current=data.days.find(day=>day.id===editingDayId),budgetTHB=current?.budgetTHB||0,places=[...document.querySelectorAll<HTMLElement>('.place-editor-row')].map(row=>({id:row.dataset.placeId||crypto.randomUUID(),name:row.querySelector<HTMLInputElement>('.place-name')?.value.trim()||'',address:row.querySelector<HTMLInputElement>('.place-address')?.value.trim()||'',mapUrl:row.querySelector<HTMLInputElement>('.place-map')?.value.trim()||''})).filter(place=>place.name||place.address||place.mapUrl);if(!date||!title){showToast('กรุณาตรวจสอบข้อมูลแผนรายวัน','error');return}if(places.some(place=>!place.name)){showToast('กรุณาใส่ชื่อสถานที่ หรือเอาแถวที่ไม่ใช้แล้วออก','error');return}if(data.days.some(day=>day.date===date&&day.id!==editingDayId)){showToast('วันที่นี้มีแผนอยู่แล้ว','error');return}const next:DayPlan={id:editingDayId||crypto.randomUUID(),date,title,activities,budgetTHB,places};if(editingDayId){data.days=data.days.map(day=>day.id===editingDayId?next:day);data.expenses=data.expenses.map(expense=>expense.dayId===editingDayId?{...expense,date}:expense)}else data.days.push(next);selectedDayId=next.id;editingDayId=null;document.body.dataset.addingDay='false';save();render();showToast('บันทึกแผนรายวันแล้ว')}
function bindDaily(){document.querySelectorAll<HTMLElement>('[data-select-day]').forEach(button=>button.addEventListener('click',()=>{selectedDayId=button.dataset.selectDay||null;render()}));document.querySelector('[data-add-day]')?.addEventListener('click',()=>{editingDayId=null;document.body.dataset.addingDay='true';render()});document.querySelectorAll<HTMLElement>('[data-edit-day]').forEach(button=>button.addEventListener('click',()=>{editingDayId=button.dataset.editDay||null;document.body.dataset.addingDay='false';render()}));document.querySelectorAll<HTMLElement>('[data-delete-day]').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.deleteDay,day=data.days.find(item=>item.id===id);if(!id||!day||!confirm(`ลบแผน “${day.title}” หรือไม่? ค่าใช้จ่ายจะย้ายไปอยู่นอกแผน`))return;data.days=data.days.filter(item=>item.id!==id);data.expenses=data.expenses.map(expense=>expense.dayId===id?{...expense,dayId:null}:expense);selectedDayId=null;save();render();showToast('ลบแผนและเก็บค่าใช้จ่ายไว้นอกแผนแล้ว')}));document.querySelectorAll('[data-close-day]').forEach(button=>button.addEventListener('click',closeDayModal));document.querySelector<HTMLFormElement>('#dayForm')?.addEventListener('submit',submitDay)}
function expenseModal(){const exp=editingId?data.expenses.find(e=>e.id===editingId):null,recent=data.expenses[0],currency=exp?.currency||recent?.currency||'THB',payerId=exp?.payerId||recent?.payerId||data.settings.travelers[0].id;return `<div class="modal-backdrop" role="presentation"><form class="modal expense-sheet" id="expenseForm" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal-head"><h2 id="modalTitle">${exp?'แก้ไข':'เพิ่ม'}ค่าใช้จ่าย</h2><button class="icon-btn" type="button" data-close aria-label="ปิด">${icon('close')}</button></div><div class="form-grid expense-primary-fields"><div class="field"><label for="expItem">รายการ</label><input class="input" id="expItem" value="${esc(exp?.item||'')}" required autofocus></div><div class="field"><label for="expAmount">จำนวนเงิน</label><input class="input" id="expAmount" type="number" inputmode="decimal" min="0" step="0.01" value="${exp?.amount||''}" required></div><div class="field"><label for="expCurrency">สกุลเงิน</label><select class="select" id="expCurrency"><option ${currency==='THB'?'selected':''}>THB</option><option ${currency==='VND'?'selected':''}>VND</option></select></div><div class="field"><label for="expCategory">หมวดหมู่</label><select class="select" id="expCategory">${categories.map(c=>`<option value="${c}" ${exp?.category===c?'selected':''}>${categoryLabels[c]}</option>`).join('')}</select></div><div class="field"><label for="expStatus">สถานะ</label><select class="select" id="expStatus"><option value="planned" ${exp?.status==='planned'?'selected':''}>คาดการณ์</option><option value="paid" ${exp?.status==='paid'?'selected':''}>จ่ายแล้ว</option></select></div></div><details class="expense-form-more" ${exp?'open':''}><summary>รายละเอียดเพิ่มเติม</summary><div class="form-grid"><div class="field"><label for="expDate">วันที่</label><input class="input" id="expDate" type="date" value="${exp?.date||data.settings.startDate}" required></div><div class="field"><label for="expPayer">ผู้จ่าย</label><select class="select" id="expPayer">${data.settings.travelers.map(p=>`<option value="${p.id}" ${payerId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label for="expNote">หมายเหตุ</label><textarea class="textarea" id="expNote" rows="2">${esc(exp?.note||'')}</textarea></div></div></details><div class="modal-actions"><button class="btn" type="button" data-close>ยกเลิก</button><button class="btn primary" type="submit">บันทึกรายการ</button></div></form></div>`}
function deleteModal(){const exp=data.expenses.find(e=>e.id===pendingDelete);return `<div class="modal-backdrop"><div class="modal" role="alertdialog" aria-modal="true" aria-labelledby="deleteTitle"><div class="modal-head"><h2 id="deleteTitle">ลบรายการนี้หรือไม่?</h2></div><p>“${esc(exp?.item||'รายการนี้')}” จะถูกลบออกจากสรุปค่าใช้จ่าย คุณไม่สามารถย้อนกลับได้</p><div class="modal-actions"><button class="btn" data-close>ยกเลิก</button><button class="btn danger" id="confirmDelete">${icon('trash')} ลบรายการ</button></div></div></div>`}
function bindTravelerPicker(){document.querySelectorAll('[data-change-traveler]').forEach(button=>button.addEventListener('click',()=>{choosingTraveler=true;render()}));document.querySelector('[data-close-traveler]')?.addEventListener('click',()=>{choosingTraveler=false;render()});document.querySelectorAll<HTMLElement>('[data-select-traveler]').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.selectTraveler;if(!id||!data.settings.travelers.some(person=>person.id===id))return;selectedTravelerId=id;choosingTraveler=false;editingPackingId=null;document.body.dataset.addingPacking='false';try{localStorage.setItem(TRAVELER_KEY,id)}catch{/* The picker will appear again if this browser blocks storage. */}render();showToast(`สวัสดี ${currentTraveler()?.name||''}`)}))}
let activeSpeechButton:HTMLElement|null=null
function speakVietnamese(text:string,button:HTMLElement){if(!('speechSynthesis'in window)||typeof SpeechSynthesisUtterance==='undefined'){showToast('อุปกรณ์นี้ไม่รองรับการอ่านออกเสียง','error');return}window.speechSynthesis.cancel();activeSpeechButton?.classList.remove('speaking');activeSpeechButton?.setAttribute('aria-pressed','false');const utterance=new SpeechSynthesisUtterance(text),voices=window.speechSynthesis.getVoices();utterance.lang='vi-VN';utterance.voice=voices.find(voice=>voice.lang.toLowerCase()==='vi-vn')||voices.find(voice=>voice.lang.toLowerCase().startsWith('vi'))||null;utterance.rate=.86;utterance.pitch=1;activeSpeechButton=button;button.classList.add('speaking');button.setAttribute('aria-pressed','true');const finish=()=>{if(activeSpeechButton!==button)return;button.classList.remove('speaking');button.setAttribute('aria-pressed','false');activeSpeechButton=null};utterance.onend=finish;utterance.onerror=event=>{finish();if(event.error!=='canceled'&&event.error!=='interrupted')showToast('ไม่สามารถเล่นเสียงบนอุปกรณ์นี้ได้','error')};window.speechSynthesis.speak(utterance)}
function bindVietnameseSpeech(root:HTMLElement|null){root?.addEventListener('click',event=>{const button=(event.target as HTMLElement).closest<HTMLElement>('[data-speak-vietnamese]');if(button)speakVietnamese(button.dataset.speakVietnamese||'',button)})}
function bindPhrasebook(){const results=document.querySelector<HTMLElement>('#phrasebookResults'),search=document.querySelector<HTMLInputElement>('#phraseSearch');const updateCategoryState=()=>document.querySelectorAll<HTMLElement>('[data-phrase-category]').forEach(button=>{const active=!phraseQuery.trim()&&button.dataset.phraseCategory===phraseCategory;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))});if(search)search.addEventListener('input',()=>{phraseQuery=search.value;if(results)results.innerHTML=phrasebookResults();updateCategoryState()});document.querySelectorAll<HTMLElement>('[data-phrase-category]').forEach(button=>button.addEventListener('click',()=>{const category=button.dataset.phraseCategory as VietnamesePhraseCategory;if(!vietnamesePhraseCategories.some(item=>item.id===category))return;phraseCategory=category;phraseQuery='';try{localStorage.setItem(PHRASE_CATEGORY_KEY,category)}catch{/* Category remains selected for this session. */}render()}));bindVietnameseSpeech(results);bindVietnameseSpeech(document.querySelector<HTMLElement>('#vietnamesePhrases'))}
function render(){const app=document.querySelector<HTMLDivElement>('#app');if(!app)return;const pages:Record<View,()=>string>={overview,expenses:expenseTable,daily,guide:renderGuide,calculator:()=>calculator({exchangeRate:data.settings.exchangeRate,travelers:data.settings.travelers.length}),documents:renderTripDocuments,phrasebook};app.innerHTML=shell(pages[view]());injectViewUtilities();if(editingId!==null||document.body.dataset.adding==='true')app.insertAdjacentHTML('beforeend',expenseModal());if(view==='daily'&&(editingDayId!==null||document.body.dataset.addingDay==='true')){app.insertAdjacentHTML('beforeend',dayModal());injectDayPlacesEditor()}if(editingEssentialId)app.insertAdjacentHTML('beforeend',essentialModal());if(editingPackingId!==null||document.body.dataset.addingPacking==='true')app.insertAdjacentHTML('beforeend',packingModal());if(pendingDelete)app.insertAdjacentHTML('beforeend',deleteModal());if(guidePreviewIndex!==null)app.insertAdjacentHTML('beforeend',guidePreviewModal());if(!currentTraveler()||choosingTraveler)app.insertAdjacentHTML('beforeend',travelerPicker());bind();bindTravelerPicker();bindDaily();injectExpenseDaySelector();bindExpenseFilters();bindTripGuide();bindGuideShortcut();bindTripUtilities();bindPhrasebook();if(view==='documents')bindTripDocuments({render,back:()=>{resetTripDocumentViewer();view='guide';render();window.scrollTo(0,0)},toast:showToast})}
function bind(){document.querySelectorAll<HTMLButtonElement>('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view as View;editingId=null;pendingDelete=null;document.body.dataset.adding='false';render();window.scrollTo(0,0)});document.querySelector('#openMenu')?.addEventListener('click',()=>{document.querySelector('.sidebar')?.classList.add('open');document.querySelector('.side-overlay')?.classList.add('show')});document.querySelector('.side-overlay')?.addEventListener('click',()=>{document.querySelector('.sidebar')?.classList.remove('open');document.querySelector('.side-overlay')?.classList.remove('show')});document.querySelectorAll('[data-add]').forEach(b=>b.addEventListener('click',()=>{editingId=null;document.body.dataset.adding='true';render()}));document.querySelectorAll<HTMLElement>('[data-edit]').forEach(b=>b.onclick=()=>{editingId=b.dataset.edit||null;document.body.dataset.adding='false';render()});document.querySelectorAll<HTMLElement>('[data-delete]').forEach(b=>b.onclick=()=>{pendingDelete=b.dataset.delete||null;render()});document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>{editingId=null;pendingDelete=null;document.body.dataset.adding='false';render()}));document.querySelector('#confirmDelete')?.addEventListener('click',()=>{data.expenses=data.expenses.filter(e=>e.id!==pendingDelete);pendingDelete=null;save();render();showToast('ลบรายการแล้ว')});const search=document.querySelector<HTMLInputElement>('#searchInput');if(search)search.oninput=()=>{query=search.value;render()};const filter=document.querySelector<HTMLSelectElement>('#categoryFilter');if(filter)filter.onchange=()=>{categoryFilter=filter.value;render()};document.querySelector<HTMLFormElement>('#expenseForm')?.addEventListener('submit',submitExpense);document.querySelector<HTMLElement>('.modal [autofocus]')?.focus()}
function submitExpense(ev:Event){ev.preventDefault();const get=(id:string)=>document.querySelector<HTMLInputElement|HTMLSelectElement|HTMLTextAreaElement>(`#${id}`),amount=Number(get('expAmount')?.value),dayId=get('expDay')?.value||null,linkedDay=data.days.find(day=>day.id===dayId);if(!Number.isFinite(amount)||amount<0){showToast('กรุณาระบุจำนวนเงินที่ถูกต้อง','error');return}const next:Expense={id:editingId||crypto.randomUUID(),date:linkedDay?.date||get('expDate')?.value||'',dayId,item:get('expItem')?.value.trim()||'',category:get('expCategory')?.value as Category,amount,currency:get('expCurrency')?.value as Currency,payerId:get('expPayer')?.value||data.settings.travelers[0].id,status:get('expStatus')?.value as Status,note:get('expNote')?.value.trim()||''};if(!next.date||!next.item){showToast('กรุณากรอกวันที่และชื่อรายการ','error');return}if(editingId)data.expenses=data.expenses.map(e=>e.id===editingId?next:e);else data.expenses.unshift(next);editingId=null;document.body.dataset.adding='false';delete document.body.dataset.expenseDay;save();render();showToast('บันทึกรายการแล้ว')}
function registerWebMCP(){if(!document.modelContext?.registerTool)return;document.modelContext.registerTool({name:'read_trip_summary',title:'อ่านสรุปทริปดานัง',description:'อ่านงบประมาณ ยอดจ่ายแล้ว ยอดคาดการณ์ และยอดคงเหลือ',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>totals()});document.modelContext.registerTool({name:'add_trip_expense',title:'เพิ่มค่าใช้จ่ายทริป',description:'เพิ่มค่าใช้จ่ายใหม่และอัปเดตยอดสรุปของทริปดานัง',inputSchema:{type:'object',properties:{date:{type:'string'},item:{type:'string'},category:{type:'string',enum:[...categories]},amount:{type:'number',minimum:0},currency:{type:'string',enum:['THB','VND']},payerId:{type:'string'},status:{type:'string',enum:['paid','planned']},note:{type:'string'}},required:['date','item','category','amount','currency','payerId','status'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:(input:Omit<Expense,'id'>)=>{if(!input.item?.trim()||input.amount<0||!data.settings.travelers.some(p=>p.id===input.payerId))throw new Error('ข้อมูลค่าใช้จ่ายไม่ถูกต้อง');const expense={...input,id:crypto.randomUUID(),note:input.note||''};data.expenses.unshift(expense);save();render();return{id:expense.id,totalTHB:totals().all}}})}
async function initialize(){render();const versionAtStart=localChangeVersion;try{const {loadOrCreateTrip,saveTrip,subscribeToTrip}=await getCloud();if(hasPendingSave){const pendingVersion=localChangeVersion;await saveTrip(clone(data));if(pendingVersion===localChangeVersion)setPendingSave(false)}else{const remoteData=await loadOrCreateTrip(data);if(!hasPendingSave&&localChangeVersion===versionAtStart){data=clone(remoteData);saveLocal()}}syncState=hasPendingSave?'saving':'synced';render();subscribeToTrip(next=>{if(hasPendingSave||JSON.stringify(next)===JSON.stringify(data))return;data=clone(next);saveLocal();render();showToast('อัปเดตข้อมูลจากอีกอุปกรณ์แล้ว')})}catch{syncState='offline';render();showToast('เชื่อมฐานข้อมูลไม่ได้ กำลังใช้ข้อมูลในเครื่อง','error')}}
registerCalculatorEvents(()=>{if(view==='calculator')render()});window.addEventListener('calculator-create-expense',(event)=>{const detail=(event as CustomEvent<{amount:number;currency:Currency}>).detail;editingId=null;document.body.dataset.adding='true';render();const amount=document.querySelector<HTMLInputElement>('#expAmount'),currency=document.querySelector<HTMLSelectElement>('#expCurrency');if(amount)amount.value=String(detail.amount);if(currency)currency.value=detail.currency});window.addEventListener('calculator-exchange-rate-change',(event)=>{const rate=(event as CustomEvent<{exchangeRate:number}>).detail.exchangeRate;if(!Number.isFinite(rate)||rate<=0)return;data.settings.exchangeRate=rate;save();showToast('บันทึกอัตราแลกเปลี่ยนแล้ว')});window.addEventListener('online',()=>{if(hasPendingSave)void flushSave()});registerWebMCP();void initialize()
